#include "platform/text_queue.h"
#include <cassert>
int main() {
    AsciiQueue<4> q;
    assert(q.push('A') && q.push('B') && q.push('C'));
    assert(!q.push('D'));
    assert(q.pop() == 'A');
    assert(q.push('D'));
    assert(q.pop() == 'B');
    assert(q.pop() == 'C');
    assert(q.pop() == 'D');
    assert(q.pop() == 0);
}
